<a class="reading-back" href="<?= $this->h($this->url('/organizations')) ?>">بازگشت به مجموعه‌ها</a><header class="card organization-hero"><span class="eyebrow"><?= $this->icon('home') ?>یک مجموعه، چند مسیرِ تجربه</span><h1><?= $this->h($organization['name']) ?></h1><p><?= $this->h($organization['description']) ?></p><?php if($organization['province_name']): ?><p><?= $this->icon('pin') ?>محل استقرار: <?= $this->h($organization['province_name'].' · '.($organization['county_name']??'شهرستان ثبت نشده')) ?></p><?php endif; ?><div class="row"><span class="tag"><?= $this->number($experiences['total']) ?> تجربه</span><span class="tag"><?= $this->number($mentors['total']) ?> مرشد مرتبط</span></div><p class="notice">این ارتباط از تجربه‌های تأییدشده شکل گرفته و به معنی عضویت فعلی مرشد در مجموعه نیست. محل اجرای هر تجربه می‌تواند با محل استقرار مجموعه متفاوت باشد.</p></header>
<section class="card section"><h2>موضوع‌ها و مسئله‌های شکل‌گرفته از تجربه‌ها</h2><div class="row"><?php foreach($classifications as $term): ?><a class="tag" href="<?= $this->h($this->url('/atlas?organization_id='.$organization['id'].'&'.$term['kind'].'='.$term['id'])) ?>"><?= $this->h($term['title']) ?></a><?php endforeach; ?><?php if(!$classifications): ?><p class="muted">هنوز موضوع یا مسئله‌ای برای این تجربه‌ها ثبت نشده است.</p><?php endif; ?></div></section><section class="section"><h2>تجربه‌های این مجموعه</h2><div class="atlas-results"><?php $layer='experiences';foreach($experiences['rows'] as $row){require __DIR__.'/atlas-result.php';} ?></div></section><section class="section"><h2>از تجربه به مرشد</h2><div class="atlas-results"><?php $layer='mentors';foreach($mentors['rows'] as $row){require __DIR__.'/atlas-result.php';} ?></div></section>

<nav class="row section" aria-label="صفحه‌های تجربه و مرشد مجموعه"><?php foreach(['experiences'=>['page','تجربه‌ها'],'mentors'=>['mentor_page','مرشدها']] as $key=>[$param,$label]):$listing=$$key;if($listing['page']>1): ?><a class="secondary" href="<?= $this->h($this->url('/organization?id='.$organization['id'].'&'.$param.'='.($listing['page']-1))) ?>"><?= $label ?>، صفحهٔ قبل</a><?php endif;if($listing['page']*20<$listing['total']): ?><a class="secondary" href="<?= $this->h($this->url('/organization?id='.$organization['id'].'&'.$param.'='.($listing['page']+1))) ?>"><?= $label ?>، صفحهٔ بعد</a><?php endif;endforeach; ?></nav>
